import React, { useEffect, useState } from 'react';
import '../css/FormCard.css'; // Reuse the yellow-black styles

export default function UserProfilePage() {
  const [user, setUser] = useState(null);

  // Example: Replace with actual user fetching logic or context
  useEffect(() => {
    const storedUser = JSON.parse(localStorage.getItem('user')); // or fetch from API
    setUser(storedUser);
  }, []);

  if (!user) {
    return (
      <div className="form-container">
        <div className="form-card">
          <p>⚠️ No user information available. Please log in.</p>
        </div>
      </div>
    );
  }

  return (
    <div className="form-container">
      <div className="form-card">
        <h2>User Profile</h2>
        <p><strong>Username:</strong> {user.username}</p>
        <p><strong>Role:</strong> {user.role}</p>
        {user.id && <p><strong>User ID:</strong> {user.id}</p>}
      </div>
    </div>
  );
}
